    // exact lc_rep_instruction equality is mandatory in the result, never silently repaired here.
    atomic_store_explicit(&saved_address,(uintptr_t)info->si_addr,memory_order_relaxed);
    atomic_store_explicit(&saved_rip,context->uc_mcontext->__ss.__rip,memory_order_relaxed);
    atomic_store_explicit(&saved_rcx,context->uc_mcontext->__ss.__rcx,memory_order_relaxed);
    atomic_store_explicit(&saved_rsi,context->uc_mcontext->__ss.__rsi,memory_order_relaxed);
    atomic_store_explicit(&saved_rdi,context->uc_mcontext->__ss.__rdi,memory_order_relaxed);
    atomic_store_explicit(&saved_rflags,context->uc_mcontext->__ss.__rflags,memory_order_relaxed);
    atomic_store_explicit(&saved_signal,number,memory_order_relaxed);
    atomic_store_explicit(&saved_code,info->si_code,memory_order_relaxed);
    atomic_store_explicit(&seen,1,memory_order_relaxed);
