    int contiguous=1;for(unsigned i=prefix;i<COPY_BYTES;i++)if(output[i]!=SENTINEL)contiguous=0;
    int fault_sentinels=outside_intact(destination,(size_t)page);
    char fault_hex[COPY_BYTES*2+1];hex_bytes(output,fault_hex);
