    uint64_t rcx=atomic_load(&saved_rcx),rflags=atomic_load(&saved_rflags);
    int fault_seen=atomic_load(&seen),signal_number=atomic_load(&saved_signal),code=atomic_load(&saved_code);
    int rip_matches=rip==(uintptr_t)lc_rep_instruction;
