        prefix==READABLE_PREFIX && contiguous && fault_sentinels && rcx==COPY_BYTES-READABLE_PREFIX &&
        rsi==(uintptr_t)input+READABLE_PREFIX && rdi==(uintptr_t)output+READABLE_PREFIX;
