    initialize_destination(destination,(size_t)page);Completion complete={0};copy_rep(input,output,COPY_BYTES,&complete);
    int completion_bytes=1;for(unsigned i=0;i<COPY_BYTES;i++)if(output[i]!=pattern(i))completion_bytes=0;
    int completion_sentinels=outside_intact(destination,(size_t)page);
